require_once '../../middleware/jsonMiddleware.php';require_once '../../middleware/requestLogger.php';require_once '../../middleware/corsMiddleware.php';require_once '../../middleware/authMiddleware.php';require_once '../../utils/response.php';require_once '../../config/database.php';use MongoDB\BSON\ObjectId;setJsonResponse();handleCors();logRequest();requireCustomer();if($_SERVER['REQUEST_METHOD']!=='GET')sendResponse(false,'Method not allowed.',null,405);try{$c=getDatabase()->bookings->find(['userId'=>new ObjectId($_SESSION['user_id'])],['sort'=>['createdAt'=>-1]]);$list=[];foreach($c as $b)$list[]=['id'=>(string)$b['_id'],'vehicleName'=>$b['vehicleName']??'','vehicleType'=>$b['vehicleType']??'Car','startDate'=>$b['startDate']->toDateTime()->format('Y-m-d'),'endDate'=>$b['endDate']->toDateTime()->format('Y-m-d'),'pickupLocation'=>$b['pickupLocation']??'—','returnLocation'=>$b['returnLocation']??'—','totalDays'=>(int)($b['totalDays']??0),'pricePerDay'=>(float)($b['pricePerDay']??0),'totalPrice'=>(float)($b['totalPrice']??0),'status'=>$b['status']??'Pending','paymentStatus'=>$b['paymentStatus']??'Not Paid','paymentMethod'=>$b['paymentMethod']??'','paymentReference'=>$b['paymentReference']??''];sendResponse(true,'Booking history retrieved',$list);}catch(Throwable $e){sendResponse(false,'Failed to retrieve bookings.',null,500);}
